-- ts-design-studio 1.0.0 – projekty, verze a záznam akcí (SQLite)
CREATE TABLE IF NOT EXISTS studio_projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(160) NOT NULL, source VARCHAR(10) NOT NULL, lead_ref VARCHAR(64) NOT NULL DEFAULT '', audit_ref VARCHAR(64) NOT NULL DEFAULT '', template VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', owner_uid INTEGER NOT NULL DEFAULT 0, current_num INTEGER NOT NULL DEFAULT 0, brief TEXT NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL);
CREATE TABLE IF NOT EXISTS studio_versions (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, num INTEGER NOT NULL, parent_num INTEGER NOT NULL DEFAULT 0, kind VARCHAR(10) NOT NULL, author_uid INTEGER NOT NULL DEFAULT 0, author_kind VARCHAR(10) NOT NULL, message VARCHAR(500) NOT NULL DEFAULT '', files TEXT NOT NULL, content TEXT NOT NULL, tokens TEXT NOT NULL, checks TEXT NOT NULL, status VARCHAR(10) NOT NULL, created_at VARCHAR(19) NOT NULL, UNIQUE (project_id, num));
CREATE TABLE IF NOT EXISTS studio_log (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, num INTEGER NOT NULL DEFAULT 0, uid INTEGER NOT NULL DEFAULT 0, action VARCHAR(30) NOT NULL, detail VARCHAR(500) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL);
CREATE INDEX IF NOT EXISTS studio_log_project ON studio_log (project_id, id);
